def bisection(f, a, b, eps=1e-8, max_iter=100):
    """零点定理/二分法求方程 f(x)=0 在 [a,b] 内的根，
    要求 f(a)*f(b) < 0。"""
    if f(a) * f(b) >= 0:
        return None  # 不满足零点定理条件
    for _ in range(max_iter):
        mid = (a + b) / 2.0
        fmid = f(mid)
        if abs(fmid) < eps or (b - a) / 2 < eps:
            return mid
        if f(a) * fmid < 0:
            b = mid
        else:
            a = mid
    return (a + b) / 2.0

# 例：求 x^3 - x - 1 = 0 在 [1, 2] 内的实根
f = lambda x: x**3 - x - 1
root = bisection(f, 1, 2)
print(f"x^3 - x - 1 = 0 的实根约为: {root:.8f}")
print(f"代入验证: f({root:.8f}) = {f(root):.10f}")
